<?php
/** XLSX chuẩn cho PPCT và Sổ đầu bài, có hỗ trợ ảnh chữ ký trong ô. */
function lb_xlsx_xml($value): string { return htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8'); }
function lb_xlsx_col(int $number): string { $name='';while($number>0){$number--;$name=chr(65+$number%26).$name;$number=intdiv($number,26);}return$name; }
function lb_xlsx_text(string $ref,$value,int $style=0): string { return '<c r="'.$ref.'" t="inlineStr" s="'.$style.'"><is><t xml:space="preserve">'.lb_xlsx_xml($value).'</t></is></c>'; }
function lb_xlsx_number(string $ref,$value,int $style=0): string { return '<c r="'.$ref.'" s="'.$style.'"><v>'.(float)$value.'</v></c>'; }
function lb_xlsx_zip(array $files,string $target): bool { if(!class_exists('ZipArchive'))return false;$zip=new ZipArchive();if($zip->open($target,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)return false;foreach($files as$name=>$content)$zip->addFromString($name,$content);$zip->close();return true; }
function lb_xlsx_base_files(string $title,string $sheetName,string $sheetXml,string $stylesXml,array $extra=[]): array {
    $now=gmdate('Y-m-d\TH:i:s\Z');$types='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/><Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>'.(!empty($extra['drawing'])?'<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>':'').'</Types>';
    $files=['[Content_Types].xml'=>$types,'_rels/.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/><Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/></Relationships>','xl/workbook.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets><sheet name="'.lb_xlsx_xml($sheetName).'" sheetId="1" r:id="rId1"/></sheets></workbook>','xl/_rels/workbook.xml.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>','xl/worksheets/sheet1.xml'=>$sheetXml,'xl/styles.xml'=>$stylesXml,'docProps/core.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>'.lb_xlsx_xml($title).'</dc:title><dc:creator>CDS Xín Mần</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">'.$now.'</dcterms:created></cp:coreProperties>','docProps/app.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes"><Application>CDS</Application><TitlesOfParts><vt:vector size="1" baseType="lpstr"><vt:lpstr>'.lb_xlsx_xml($sheetName).'</vt:lpstr></vt:vector></TitlesOfParts></Properties>'];return array_merge($files,$extra['files']??[]);
}
function lb_xlsx_styles(): string { return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="3"><font><sz val="11"/><name val="Times New Roman"/></font><font><b/><sz val="16"/><name val="Times New Roman"/></font><font><b/><sz val="10"/><color rgb="FFFFFFFF"/><name val="Times New Roman"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF1F4E78"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="2"><border/><border><left style="thin"><color rgb="FF808080"/></left><right style="thin"><color rgb="FF808080"/></right><top style="thin"><color rgb="FF808080"/></top><bottom style="thin"><color rgb="FF808080"/></bottom><diagonal/></border></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="7"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment vertical="center"/></xf><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="2" fillId="2" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center" wrapText="1"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0" applyAlignment="1"><alignment horizontal="center" vertical="center"/></xf><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyAlignment="1"><alignment horizontal="right" vertical="center"/></xf></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>'; }
function lb_ppct_template_xlsx(string $target): bool {
    $heads=['Môn','Khối','Tiết PPCT','Tên bài / nội dung','Ghi chú'];$rows=[];$cells='';foreach($heads as$i=>$h)$cells.=lb_xlsx_text(lb_xlsx_col($i+1).'1',$h,2);$rows[]='<row r="1" ht="30">'.$cells.'</row>';for($n=2;$n<=101;$n++){$cells='';for($i=1;$i<=5;$i++)$cells.=lb_xlsx_text(lb_xlsx_col($i).$n,'',$i===3?4:3);$rows[]='<row r="'.$n.'" ht="23">'.$cells.'</row>';}$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="1" width="22" customWidth="1"/><col min="2" max="2" width="10" customWidth="1"/><col min="3" max="3" width="14" customWidth="1"/><col min="4" max="4" width="55" customWidth="1"/><col min="5" max="5" width="32" customWidth="1"/></cols><sheetData>'.implode('',$rows).'</sheetData><autoFilter ref="A1:E101"/><pageMargins left="0.4" right="0.4" top="0.5" bottom="0.5" header="0.2" footer="0.2"/></worksheet>';return lb_xlsx_zip(lb_xlsx_base_files('Mẫu nhập PPCT','PPCT',$sheet,lb_xlsx_styles()),$target);
}
function lb_lesson_book_xlsx(array $rows,array $week,string $class,string $target): bool {
    $title='SỔ ĐẦU BÀI - LỚP '.$class.' - '.($week['label']??'');$heads=['Thứ, ngày/tháng','Buổi','Tiết','Lớp','Môn học','Tiết PPCT','Đầu bài / nội dung công việc','Học sinh vắng trong tiết','Nhận xét của giáo viên','Xếp loại tiết học','Trạng thái','Giáo viên thực tế','Ký tên'];$days=[1=>'Thứ Hai',2=>'Thứ Ba',3=>'Thứ Tư',4=>'Thứ Năm',5=>'Thứ Sáu',6=>'Thứ Bảy',7=>'Chủ nhật'];$labels=['pending'=>'Chưa hoàn thành','taught'=>'Đã dạy','substitute'=>'Dạy thay','makeup'=>'Dạy bù','online'=>'Trực tuyến','holiday'=>'Nghỉ lễ','teacher_absent'=>'GV nghỉ','class_absent'=>'Lớp nghỉ','postponed'=>'Hoãn','cancelled'=>'Hủy'];$sheetRows=[];$sheetRows[]='<row r="1" ht="30">'.lb_xlsx_text('A1',$title,1).'</row>';$sheetRows[]='<row r="2" ht="22">'.lb_xlsx_text('A2','Từ ngày '.date('d/m/Y',strtotime($week['start'])).' đến ngày '.date('d/m/Y',strtotime($week['end'])),5).'</row>';$cells='';foreach($heads as$i=>$h)$cells.=lb_xlsx_text(lb_xlsx_col($i+1).'3',$h,2);$sheetRows[]='<row r="3" ht="40">'.$cells.'</row>';$anchors=[];$rels=[];$media=[];$imageNo=0;
    foreach($rows as$index=>$r){$n=$index+4;$vals=[($days[(int)date('N',strtotime((string)$r['date']))]??'').' '.date('d/m/Y',strtotime((string)$r['date'])),$r['session']??'',$r['period']??'',$r['class']??'',$r['subject']??'',$r['ppct_period']??'',$r['lesson_title']??'',$r['absent_names']??'',$r['teacher_comment']??'',$r['rating']??'',$labels[$r['status']??'pending']??($r['status']??''),$r['actual_teacher']??'',''];$cells='';foreach($vals as$i=>$v){$ref=lb_xlsx_col($i+1).$n;$cells.=is_numeric($v)&&in_array($i,[2,5],true)?lb_xlsx_number($ref,$v,4):lb_xlsx_text($ref,$v,in_array($i,[0,1,2,3,5,9,10,12],true)?4:3);}$sheetRows[]='<row r="'.$n.'" ht="44">'.$cells.'</row>';$path=(string)($r['signature_path']??'');if(!empty($r['signed_at'])&&$path!==''&&is_file($path)){++$imageNo;$media['xl/media/signature'.$imageNo.'.png']=(string)file_get_contents($path);$rels[]='<Relationship Id="rId'.$imageNo.'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/signature'.$imageNo.'.png"/>';$rowIndex=$n-1;$anchors[]='<xdr:oneCellAnchor><xdr:from><xdr:col>12</xdr:col><xdr:colOff>60000</xdr:colOff><xdr:row>'.$rowIndex.'</xdr:row><xdr:rowOff>70000</xdr:rowOff></xdr:from><xdr:ext cx="1140000" cy="380000"/><xdr:pic><xdr:nvPicPr><xdr:cNvPr id="'.$imageNo.'" name="Chữ ký '.lb_xlsx_xml($r['signed_by']??'').'"/><xdr:cNvPicPr/></xdr:nvPicPr><xdr:blipFill><a:blip xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" r:embed="rId'.$imageNo.'"/><a:stretch xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:fillRect/></a:stretch></xdr:blipFill><xdr:spPr><a:xfrm xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:off x="0" y="0"/><a:ext cx="1140000" cy="380000"/></a:xfrm><a:prstGeom xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" prst="rect"><a:avLst/></a:prstGeom></xdr:spPr></xdr:pic><xdr:clientData/></xdr:oneCellAnchor>';}}
    $last=max(3,count($rows)+3);$sheet='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><dimension ref="A1:M'.$last.'"/><sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="3" topLeftCell="A4" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><sheetFormatPr defaultRowHeight="20"/><cols><col min="1" max="1" width="17"/><col min="2" max="2" width="10"/><col min="3" max="3" width="7"/><col min="4" max="4" width="9"/><col min="5" max="5" width="15"/><col min="6" max="6" width="10"/><col min="7" max="7" width="35"/><col min="8" max="8" width="26"/><col min="9" max="9" width="28"/><col min="10" max="10" width="14"/><col min="11" max="11" width="15"/><col min="12" max="12" width="24"/><col min="13" max="13" width="18"/></cols><sheetData>'.implode('',$sheetRows).'</sheetData><mergeCells count="2"><mergeCell ref="A1:M1"/><mergeCell ref="A2:M2"/></mergeCells><autoFilter ref="A3:M'.$last.'"/><pageMargins left="0.25" right="0.25" top="0.35" bottom="0.35" header="0.15" footer="0.15"/><pageSetup orientation="landscape" paperSize="8" fitToWidth="1" fitToHeight="0"/>'.($anchors?'<drawing r:id="rId1"/>':'').'</worksheet>';$extra=[];if($anchors){$extra=['drawing'=>true,'files'=>array_merge(['xl/worksheets/_rels/sheet1.xml.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing1.xml"/></Relationships>','xl/drawings/drawing1.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><xdr:wsDr xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'.implode('',$anchors).'</xdr:wsDr>','xl/drawings/_rels/drawing1.xml.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'.implode('',$rels).'</Relationships>'],$media)];}$sheetName=preg_replace('/[\\\/?*\[\]:]+/u',' ','Lớp '.$class)?:'So dau bai';$sheetName=function_exists('mb_substr')?mb_substr($sheetName,0,31,'UTF-8'):substr($sheetName,0,31);return lb_xlsx_zip(lb_xlsx_base_files($title,$sheetName,$sheet,lb_xlsx_styles(),$extra),$target);
}
